fulfill.run:
const re = $self.address.entire
const STORAGE_KEY = 'devtool_mod_request'
const DEFAULT_STATE = {
  enabled: false,
  rules: [{ id: 'custom_mod_request_gray', type: 'cookie', key: '__gray', value: '1', selected: true }],
}
$self.state = $observable({ enabled: false, rules: [] })
$self.saveModRequest = async (s) => {
  await $chrome.storage.local.set({ [STORAGE_KEY]: { enabled: s.enabled, rules: JSON.parse(JSON.stringify(s.rules || [])) } })
}
$self.loadModRequest = async () => {
  try {
    const res = await $chrome.storage.local.get(STORAGE_KEY)
    const s = res[STORAGE_KEY] || DEFAULT_STATE
    $self.state.enabled = !!s.enabled
    $self.state.rules = s.rules || []
  } catch (e) {
    $logger.error('加载修改请求配置失败', e)
    $message.error('加载修改请求配置失败')
  }
}
$self.showAddOrUpdateDialog = (row) => {
  const dialog = $self.query(re + '.editDialog').take()
  if (dialog) {
    dialog.value = row ? { id: row.id, type: row.type, key: row.key, value: row.value } : { type: 'header', key: '', value: '' }
    dialog.setComponentProps({ open: true, title: row ? '编辑规则' : '新增规则' })
  }
}
$self.handleToggleRule = async (row, selected) => {
  if (!row) return
  const list = $self.state.rules.map((r) => (r.id === row.id ? { ...r, selected } : r))
  try {
    await $self.saveModRequest({ enabled: $self.state.enabled, rules: list })
    $self.state.rules = list
  } catch (e) {
    $message.error('操作失败')
  }
}
$self.handleDelete = async (row) => {
  if (!row) return
  const list = $self.state.rules.filter((r) => r.id !== row.id)
  try {
    await $self.saveModRequest({ enabled: $self.state.enabled, rules: list })
    $self.state.rules = list
    $message.success('规则已删除')
  } catch (e) {
    $message.error('删除失败')
  }
}
$effect(() => { $self.loadModRequest() }, [])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('modRequestSettingsDiv') + 'modRequestSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => { $self.value = rf.state.enabled }, [rf.state.enabled])
$props({
  onChange: async (checked) => {
    try {
      await rf.saveModRequest({ enabled: checked, rules: rf.state.rules })
      rf.state.enabled = checked
      $message.success(checked ? '修改请求已开启' : '修改请求已关闭')
    } catch (e) {
      $message.error('操作失败')
    }
  },
})

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('modRequestSettingsDiv') + 'modRequestSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const en = rf.state.enabled
  const count = (rf.state.rules || []).filter((r) => r.selected).length
  $self.value = en ? '生效中：' + count + ' 条规则' : ''
  $self.display = en ? 'visible' : 'none'
}, [rf.state.enabled, rf.state.rules])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('modRequestSettingsDiv') + 'modRequestSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const en = rf.state.enabled
  $self.value = en ? '' : '修改请求已关闭，所有规则不生效'
  $self.display = en ? 'none' : 'visible'
}, [rf.state.enabled])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('modRequestSettingsDiv') + 'modRequestSettingsDiv'.length)
const rf = $self.query(re).take()
$props({ onClick: () => rf.showAddOrUpdateDialog(null) })

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('modRequestSettingsDiv') + 'modRequestSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  const TYPE_LABEL = { header: 'Header', cookie: 'Cookie', query: 'Query' }
  const TYPE_COLOR = { header: 'blue', cookie: 'orange', query: 'purple' }
  const t = (row && row.type) || 'header'
  $self.value = TYPE_LABEL[t] || t
  $props({ color: TYPE_COLOR[t] || 'default' })
}, [rf.state.rules])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('modRequestSettingsDiv') + 'modRequestSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  $self.value = row ? row.key : ''
}, [rf.state.rules])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('modRequestSettingsDiv') + 'modRequestSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  $self.value = row ? row.value : ''
}, [rf.state.rules])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('modRequestSettingsDiv') + 'modRequestSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  const sel = !!(row && row.selected)
  $self.value = sel ? '生效中' : '已停用'
  $props({ color: sel ? 'green' : 'default' })
}, [rf.state.rules])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('modRequestSettingsDiv') + 'modRequestSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  const sel = !!(row && row.selected)
  $props({
    children: sel ? '停用' : '启用',
    icon: sel ? 'MinusCircleOutlined' : 'CheckCircleOutlined',
    type: sel ? 'default' : 'dashed',
    onClick: () => rf.handleToggleRule(row, !sel),
  })
}, [rf.state.rules])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('modRequestSettingsDiv') + 'modRequestSettingsDiv'.length)
const rf = $self.query(re).take()
$props({ onClick: () => { const row = $utils.getArrayFieldRow($self, 'ArrayTable'); rf.showAddOrUpdateDialog(row) } })

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('modRequestSettingsDiv') + 'modRequestSettingsDiv'.length)
const rf = $self.query(re).take()
$props({ onConfirm: async () => { const row = $utils.getArrayFieldRow($self, 'ArrayTable'); await rf.handleDelete(row) } })

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('modRequestSettingsDiv') + 'modRequestSettingsDiv'.length)
const rf = $self.query(re).take()
$props({
  onCancel: () => { $self.componentProps.open = false },
  onOk: () => {
    $self.validate().then(async () => {
      const form = $self.value
      const TYPE_LABEL = { header: 'Header', cookie: 'Cookie', query: 'Query' }
      const exists = rf.state.rules.some((r) => r.type === form.type && r.key === form.key && r.id !== form.id)
      if (exists) {
        const kField = $self.query($self.address.entire + '.key').take()
        if (kField) kField.setFeedback({ type: 'error', messages: [(TYPE_LABEL[form.type] || form.type) + ' 类型下该 Key 已存在'] })
        return
      }
      const list = rf.state.rules.slice()
      const isEdit = !!form.id
      if (isEdit) {
        const old = rf.state.rules.find((r) => r.id === form.id)
        const next = { id: form.id, type: form.type, key: form.key, value: form.value, selected: old ? old.selected : true }
        const idx = list.findIndex((r) => r.id === form.id)
        if (idx >= 0) list[idx] = next
        else list.push(next)
      } else {
        list.push({ id: 'custom_mod_request_' + Date.now() + Math.random().toString(36).slice(2, 7), type: form.type, key: form.key, value: form.value, selected: true })
      }
      try {
        await rf.saveModRequest({ enabled: rf.state.enabled, rules: list })
        rf.state.rules = list
        $message.success(isEdit ? '规则已更新' : '规则已新增')
        $self.componentProps.open = false
      } catch (e) {
        $message.error('保存失败')
      }
    }).catch((e) => $logger.info('校验失败', e))
  },
})

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('modRequestSettingsDiv') + 'modRequestSettingsDiv'.length)
const dlg = $self.query(re + '.editDialog').take()
$effect(() => {
  $props({ disabled: !!(dlg && dlg.value && dlg.value.id) })
}, [dlg && dlg.value])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('modRequestSettingsDiv') + 'modRequestSettingsDiv'.length)
const dlg = $self.query(re + '.editDialog').take()
$effect(() => {
  const t = (dlg && dlg.value && dlg.value.type) || 'header'
  $self.setTitle(t === 'header' ? 'Header 名称' : t === 'cookie' ? 'Cookie Key' : 'Query 参数名')
  $props({ placeholder: t === 'header' ? '例如：x-debug-uid' : t === 'cookie' ? '例如：__gray' : '例如：debug' })
}, [dlg && dlg.value && dlg.value.type])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('modRequestSettingsDiv') + 'modRequestSettingsDiv'.length)
const dlg = $self.query(re + '.editDialog').take()
$effect(() => {
  const t = (dlg && dlg.value && dlg.value.type) || 'header'
  $self.setTitle(t === 'header' ? 'Header 值' : t === 'cookie' ? 'Cookie Value' : 'Query 参数值')
  $props({ placeholder: t === 'header' ? '例如：123456' : t === 'cookie' ? '例如：1' : '例如：true' })
}, [dlg && dlg.value && dlg.value.type])
